class IntConversionDescriptor:
      def __init__(self, *, default):
          self._default = default

def __set_name__(self, owner, name):
          self._name = "_" + name

def __get__(self, obj, type):
          if obj is None:
              return self._default

return getattr(obj, self._name, self._default)

def __set__(self, obj, value):
          setattr(obj, self._name, int(value))

@dataclass
  class InventoryItem:
      quantity_on_hand: IntConversionDescriptor = IntConversionDescriptor(default=100)

i = InventoryItem()
  print(i.quantity_on_hand)   # 100
  i.quantity_on_hand = 2.5    # calls __set__ with 2.5
  print(i.quantity_on_hand)   # 2

Note that if a field is annotated with a descriptor type, but is not assigned
a descriptor object as its default value, the field will act like a normal
field.

Python · collections --- Container datatypes · ChainMap objects

class DeepChainMap(ChainMap):
        'Variant of ChainMap that allows direct updates to inner scopes'

def __setitem__(self, key, value):
            for mapping in self.maps:
                if key in mapping:
                    mapping[key] = value
                    return
            self.maps[0][key] = value

def __delitem__(self, key):
            for mapping in self.maps:
                if key in mapping:
                    del mapping[key]
                    return
            raise KeyError(key)

>>> d = DeepChainMap({'zebra': 'black'}, {'elephant': 'blue'}, {'lion': 'yellow'})
    >>> d['lion'] = 'orange'         # update an existing key two levels down
    >>> d['snake'] = 'red'           # new keys get added to the topmost dict
    >>> del d['elephant']            # remove an existing key one level down
    >>> d                            # display result
    DeepChainMap({'zebra': 'black', 'snake': 'red'}, {}, {'lion': 'orange'})

Python · collections --- Container datatypes · deque objects

def roundrobin(*iterables):
        "roundrobin('ABC', 'D', 'EF') --> A D E B F C"
        iterators = deque(map(iter, iterables))
        while iterators:
            try:
                while True:
                    yield next(iterators[0])
                    iterators.rotate(-1)
            except StopIteration:
                # Remove an exhausted iterator.
                iterators.popleft()

The deque.rotate method provides a way to implement deque slicing and
deletion.  For example, a pure Python implementation of `del d[n]` relies on
the `rotate()` method to position elements to be popped::

def delete_nth(d, n):
        d.rotate(-n)
        d.popleft()
        d.rotate(n)

